TEST(Sto, IntConversion)
{
  int v = 0;
  EXPECT_TRUE(to("42", v));
  EXPECT_EQ(v, 42);
  EXPECT_TRUE(to("-7", v));
  EXPECT_EQ(v, -7);
}

TEST(Sto, IntInvalid)
{
  int v = 123;
  EXPECT_FALSE(to("abc", v, 99));
  EXPECT_EQ(v, 99);
  EXPECT_FALSE(to("", v, 77));
  EXPECT_EQ(v, 77);
}

