TEST(Sto, FloatConversion)
{
  float v = 0.0f;
  EXPECT_TRUE(to("3.14", v));
  EXPECT_FLOAT_EQ(v, 3.14f);
  EXPECT_TRUE(to("-2.5", v));
  EXPECT_FLOAT_EQ(v, -2.5f);
}

TEST(Sto, FloatInvalid)
{
  float v = 1.0f;
  EXPECT_FALSE(to("not_a_float", v, 9.9f));
  EXPECT_FLOAT_EQ(v, 9.9f);
}

TEST(Sto, DoubleConversion)
{
  double v = 0.0;
  EXPECT_TRUE(to("2.71828", v));
  EXPECT_DOUBLE_EQ(v, 2.71828);
}

TEST(Sto, DoubleInvalid)
{
  double v = 1.0;
  EXPECT_FALSE(to("notdouble", v, 0.0));
  EXPECT_EQ(v, 0.0);
}

TYPED_TEST(StoFPInvalidTest, NaN)
{
  auto v = TypeParam{3.14};
  EXPECT_FALSE(to<TypeParam>("nan", v, 0.0));
  EXPECT_TRUE(std::isnan(v));
}

TYPED_TEST(StoFPInvalidTest, Inf)
{
  auto v = TypeParam(4.13);
  EXPECT_FALSE(to<TypeParam>("inf", v, 0.0));
  EXPECT_TRUE(std::isinf(v));

  v = TypeParam(4.13);
  EXPECT_FALSE(to<TypeParam>("-inf", v, 0.0));
  EXPECT_TRUE(std::isinf(v));
}

