TEST(Sto, EmptyStringDefault)
{
  int v = 5;
  EXPECT_FALSE(to("", v, 42));
  EXPECT_EQ(v, 42);
  float f = 1.0f;
  EXPECT_FALSE(to("", f, 2.5f));
  EXPECT_FLOAT_EQ(f, 2.5f);
}

TEST(Sto, TrailingCharacters)
{
  // Partial parses are always considered failures
  int v = 0;
  EXPECT_FALSE(to("123abc", v, 7));
  EXPECT_EQ(v, 7);
  float f = 0.0f;
  EXPECT_FALSE(to("3.14xyz", f, 1.1f));
  EXPECT_FLOAT_EQ(f, 1.1f);
}

TEST(Sto, WhitespaceHandling)
{
  // Partial parses are always considered failures
  int v = 0;
  EXPECT_FALSE(to("  42  ", v, 24));
  EXPECT_EQ(v, 24);
  float f = 0.0f;
  EXPECT_FALSE(to("  3.14  ", f, 4.13f));
  EXPECT_FLOAT_EQ(f, 4.13f);
}

