TEST(Sto, ValidDateTime)
{
  time_t t = 0;
  EXPECT_TRUE(to("2023-11-05 12:34:56", t));
  struct tm* tm_ptr = std::localtime(&t);
  ASSERT_NE(tm_ptr, nullptr);
  EXPECT_EQ(tm_ptr->tm_year + 1900, 2023);
  EXPECT_EQ(tm_ptr->tm_mon + 1, 11);
  EXPECT_EQ(tm_ptr->tm_mday, 5);
  EXPECT_EQ(tm_ptr->tm_hour, 12);
  EXPECT_EQ(tm_ptr->tm_min, 34);
  EXPECT_EQ(tm_ptr->tm_sec, 56);
}

TEST(Sto, InvalidDateFormat)
{
  time_t t = 12345;
  EXPECT_FALSE(to("2023/11/05 12:34:56", t));
  EXPECT_EQ(t, 0);
}

TEST(Sto, EmptyStringIsTimeZero)
{
  time_t t = 12345;
  EXPECT_FALSE(to("", t));
  EXPECT_EQ(t, 0);
}

TEST(Sto, EmptyStringTimeIsDefault)
{
  time_t t = 12345;
  time_t def = 4321;
  EXPECT_FALSE(to("", t, def));
  EXPECT_EQ(t, def);
}

TEST(Sto, InvalidDate)
{
  time_t t = 12345;
  EXPECT_TRUE(to("2023-02-30 12:00:00", t));  // mktime normalizes to March 2
  struct tm* tm_ptr = std::localtime(&t);
  ASSERT_NE(tm_ptr, nullptr);
  EXPECT_NE(tm_ptr->tm_mday, 30);  // Should not be 30
}

TEST(Sto, LeapYear)
{
  time_t t = 0;
  EXPECT_TRUE(to("2020-02-29 00:00:00", t));
  struct tm* tm_ptr = std::localtime(&t);
  ASSERT_NE(tm_ptr, nullptr);
  EXPECT_EQ(tm_ptr->tm_year + 1900, 2020);
  EXPECT_EQ(tm_ptr->tm_mon + 1, 2);
  EXPECT_EQ(tm_ptr->tm_mday, 29);
}

TEST(Sto, Midnight)
{
  time_t t = 0;
  EXPECT_TRUE(to("2000-01-01 00:00:00", t));
  struct tm* tm_ptr = std::localtime(&t);
  ASSERT_NE(tm_ptr, nullptr);
  EXPECT_EQ(tm_ptr->tm_hour, 0);
  EXPECT_EQ(tm_ptr->tm_min, 0);
  EXPECT_EQ(tm_ptr->tm_sec, 0);
}

TEST(Sto, EndOfYear)
{
  time_t t = 0;
  EXPECT_TRUE(to("1999-12-31 23:59:59", t));
  struct tm* tm_ptr = std::localtime(&t);
  ASSERT_NE(tm_ptr, nullptr);
  EXPECT_EQ(tm_ptr->tm_year + 1900, 1999);
  EXPECT_EQ(tm_ptr->tm_mon + 1, 12);
  EXPECT_EQ(tm_ptr->tm_mday, 31);
  EXPECT_EQ(tm_ptr->tm_hour, 23);
  EXPECT_EQ(tm_ptr->tm_min, 59);
  EXPECT_EQ(tm_ptr->tm_sec, 59);
}

