TEST(Snums, BasicInts)
{
  std::vector<int> values;
  EXPECT_TRUE(to("1,2,3,4", values, ","));
  EXPECT_EQ(values, (std::vector<int>{1, 2, 3, 4}));
}

TEST(Snums, BasicFloats)
{
  std::vector<float> values;
  EXPECT_TRUE(to("1.1;2.2;3.3", values, ";"));
  EXPECT_EQ(values, (std::vector<float>{1.1f, 2.2f, 3.3f}));
}

TEST(Snums, SpacesAndSeparator)
{
  std::vector<int> values;
  EXPECT_TRUE(to(" 5 , 6 , 7 ", values, ","));
  EXPECT_EQ(values, (std::vector<int>{5, 6, 7}));
}

TEST(Snums, EmptyString)
{
  std::vector<int> values{42};
  EXPECT_TRUE(to("", values, ","));
  EXPECT_EQ(values.size(), 0);
}

TEST(Snums, SingleValue)
{
  std::vector<double> values;
  EXPECT_TRUE(to("42.5", values, ","));
  EXPECT_EQ(values, (std::vector<double>{42.5}));
}

TEST(Snums, InvalidNumber)
{
  std::vector<int> values{1, 2, 3};
  EXPECT_FALSE(to("1,2,x,4", values, ","));
  EXPECT_EQ(values.size(), 0);  // Should clear on error
}

TEST(Snums, CustomSeparator)
{
  std::vector<int> values;
  EXPECT_TRUE(to("8|9|10", values, "|"));
  EXPECT_EQ(values, (std::vector<int>{8, 9, 10}));
}

TEST(Snums, NegativeNumbers)
{
  std::vector<int> values;
  EXPECT_TRUE(to("-1,-2,-3", values, ","));
  EXPECT_EQ(values, (std::vector<int>{-1, -2, -3}));
}

TEST(Snums, LeadingTrailingSeparators)
{
  std::vector<int> values;
  EXPECT_TRUE(to(",1,2,3,", values, ","));
  EXPECT_EQ(values, (std::vector<int>{1, 2, 3}));
}
